function rescaleBackrestRegionPressure(frame, totalForceN, regionForcesN) {
  if ((frame.method === "per_cell_force_sum_then_region_arithmetic_mean" || frame.method === "recognized_nominal_force_map_then_region_arithmetic_mean") && regionForcesN) {
    if (regionForcesN.length !== frame.regions.length || regionForcesN.some((v) => !Number.isFinite(v) || v < 0)) {
      throw new TypeError("Matching nonnegative cell-derived region forces required");
    }
    const regions2 = frame.regions.map((region, i) => ({
      ...region,
      center: [...region.center],
      estimatedForceN: regionForcesN[i],
      forceShare: totalForceN > 0 ? regionForcesN[i] / totalForceN : 0,
      estimatedPressureKPa: region.estimatedPressureKPa === null ? null : 10 * regionForcesN[i] / region.areaCm2
    }));
    return {
      ...frame,
      totalForceN,
      regions: regions2,
      averagePressureKPa: frame.status === "estimated" ? regions2.reduce((sum3, region) => sum3 + region.estimatedPressureKPa, 0) / regions2.length : null,
      globalAreaMeanPressureKPa: frame.areaCm2 > 0 ? 10 * totalForceN / frame.areaCm2 : null
    };
  }
  const regions = frame.regions.map((region) => ({
    ...region,
    center: [...region.center],
    estimatedForceN: totalForceN * region.forceShare,
    estimatedPressureKPa: region.estimatedPressureKPa === null ? null : 10 * totalForceN * region.forceShare / region.areaCm2
  }));
  return {
    ...frame,
    totalForceN,
    regions,
    averagePressureKPa: frame.status === "estimated" ? regions.reduce((s, region) => s + region.estimatedPressureKPa, 0) / regions.length : null,
    globalAreaMeanPressureKPa: frame.areaCm2 > 0 ? 10 * totalForceN / frame.areaCm2 : null
  };
}

